  function orderRow(o) { const detailHref = `./cleanhub-pos-order-detail.html?order=${encodeURIComponent(o.no)}&customer=${encodeURIComponent(o.customer)}`; return `<div class="grid grid-cols-[125px_minmax(180px,1.2fr)_110px_105px_110px_125px_125px_90px] items-center border-t border-slate-100 px-5 py-4 text-sm hover:bg-slate-50/70"><div><a href="${detailHref}" class="font-mono text-xs font-semibold text-blue-700 hover:underline">${o.no}</a><div class="mt-1 text-[11px] text-slate-400">${formatDate(o.expire)} 到期</div></div><div class="min-w-0"><div class="truncate font-semibold text-slate-800">${esc(o.customer)} <span class="ml-1 font-normal text-slate-400">${esc(o.phone)}</span></div><div class="mt-1 truncate text-xs text-slate-500">${sourceSummary(o)}</div></div><div class="text-xs font-medium text-slate-600">${o.type}</div><div>${orderBadge(o.status)}</div><div>${paymentBadge(o.paymentStatus)}</div><div><div class="font-semibold">${money(o.paidAmount)}</div><div class="mt-1 text-[11px] text-slate-400">总额 ${money(o.total)}</div></div><div class="text-xs text-slate-500">${o.paidTime === "—" ? "尚未支付" : formatDateTime(o.paidTime)}</div><div class="flex justify-end gap-1"><a title="查看详情" aria-label="查看详情" href="${detailHref}" class="flex h-8 w-8 items-center justify-center rounded-lg text-slate-500 hover:bg-blue-50 hover:text-blue-700">${ico("eye")}</a><button title="修改" aria-label="修改订单" onclick="Orders.edit('${o.no}')" class="flex h-8 w-8 items-center justify-center rounded-lg text-slate-500 hover:bg-blue-50 hover:text-blue-700">${ico("square-pen")}</button></div></div>`; }
